svg.script:
// Study Kit auto loader (SVG), no iframes: downloads Study Kit's start page from studykit.win
// and turns this page into it. An SVG page can't document.write, so it navigates to a
// javascript: address returning the page (see run()). A <base> tag sends its files and
// requests back to studykit.win.
// The site first answers with its decoy 404 (proxy/decoy.js); the ID on that page is signed,
// and asking for "/?dpl=<ID>" gets the real start page, as the decoy's own script would.
// Reading the site's own start page needs the server's permission (Access-Control-Allow-Origin,
// see route() in server.js); without it the loader uses the copy built into it (see COPY).
(() => {
  const SITE = 'https://studykit.win/';
  const TIMEOUT_MS = 20000, EST = 210 * 1024;
  const $ = id => document.getElementById(id);
  const p = $('p'), t = $('t'), err = $('e'), bar = document.querySelector('[role=progressbar]');
  $('direct').setAttribute('href', SITE);
  let cur = 0, trickle = null;
  const show = pc => { cur = pc; p.style.width = pc + '%'; bar.setAttribute('aria-valuenow', Math.round(pc)); };
  // Keeps the bar creeping toward 90% while waiting, so it never looks stuck.
  const creep = () => { clearInterval(trickle); trickle = setInterval(() => show(cur + (90 - cur) * 0.05), 200); };

  // Downloads a page as text, moving the bar from `from` to `to` as it arrives.
  async function get(url, from, to) {
    const ac = new AbortController(), tm = setTimeout(() => ac.abort(), TIMEOUT_MS);
    try {
      const r = await fetch(url, { cache: 'no-store', credentials: 'omit', redirect: 'follow', signal: ac.signal });
      if (!r.body) return { status: r.status, text: await r.text() };
      const total = +(r.headers.get('content-length') || 0), exact = !!total && !r.headers.get('content-encoding');
      const rd = r.body.getReader(), parts = []; let got = 0;
      for (;;) {
        const q = await rd.read();
        if (q.done) break;
        parts.push(q.value); got += q.value.length;
        const f = Math.min(1, got / (exact ? total : Math.max(EST, got * 1.05)));
        if (from + (to - from) * f > cur) show(from + (to - from) * f);
      }
      const all = new Uint8Array(got); let o = 0;
      for (const c of parts) { all.set(c, o); o += c.length; }
      return { status: r.status, text: new TextDecoder('utf-8').decode(all) };
    } finally { clearTimeout(tm); }
  }

  // Study Kit's start page built into this file (public/index.html, gzip + base64), for when
  // studykit.win doesn't let other addresses read its own copy. Packed by loader/build.js.
  const COPY = '';
  const unpack = () => new Response(new Blob([Uint8Array.from(atob(COPY), c => c.charCodeAt(0))]).stream().pipeThrough(new DecompressionStream('gzip'))).text();
  // Can studykit.win be reached at all? (no-cors: needs no permission, but can't read the answer)
  async function reachable() {
    const ac = new AbortController(), tm = setTimeout(() => ac.abort(), 10000);
    try { await fetch(SITE, { mode: 'no-cors', cache: 'no-store', credentials: 'omit', signal: ac.signal }); return true; }
    catch (_) { return false; }
    finally { clearTimeout(tm); }
  }

  // The newest start page from the site: its decoy 404 carries a signed ID, and the real start
  // page is "/?dpl=<ID>". Without the server's permission to read it, the built-in copy.
  async function startPage() {
    try {
      const first = await get(SITE, 5, 20);
      const id = (/id="i">([a-z]{3}\d::[\w-]+)</.exec(first.text) || [])[1];
      const page = id ? await get(SITE + '?dpl=' + encodeURIComponent(id), 20, 95) : first;
      if (page.status !== 200 || !/<html[\s>]/i.test(page.text) || !page.text.includes('id="addressForm"')) throw new Error('not the start page');
      return page.text;
    } catch (e) {
      if (!COPY || !(await reachable())) throw e;
      show(Math.max(cur, 60));
      return unpack();
    }
  }

  // Its own addresses ("/__pd/ui/...", "/p/...") are relative, so they go to studykit.win.
  const withBase = html => {
    if (/<base[\s>]/i.test(html)) return html;
    const tag = '<base href="' + SITE + '">', head = /<head(\s[^>]*)?>/i.exec(html);
    return head ? html.slice(0, head.index + head[0].length) + tag + html.slice(head.index + head[0].length) : tag + html;
  };

  async function run() {
    err.hidden = true; show(0); show(5); creep();
    try {
      const html = withBase(await startPage());
      clearInterval(trickle); show(100);
      // A javascript: address that returns a string replaces this page with an HTML page made
      // from it, at this same address and origin (so settings storage works and a reload runs
      // the loader again). A blob: page would get an origin of its own, without storage.
      window.__studyKitPage = html;
      setTimeout(() => { location.href = 'javascript:window.__studyKitPage'; }, 50);
    } catch (e) {
      clearInterval(trickle); show(0);
      t.textContent = 'Couldn’t load Study Kit. studykit.win may be blocked on this network, or you’re offline.';
      err.hidden = false;
    }
  }
  $('retry').addEventListener('click', run);
  run();
})();
